/// Carry the notice along an exact image prefix before keeping its extension can evict it.
pub fn imageNoted(s: *const pc.Store, tokens: []const u32) bool {
    for (s.entries.items) |e| if (e.image_noted and std.mem.startsWith(u32, tokens, e.tokens) and
        @import("cache_images.zig").matches(s, e)) return true;
    return false;
}

pub fn queued(r: *Rows, kept: anytype, starts: []const u32) void {
    if (r.stopped) return;
    if (@TypeOf(kept) == *pc.Entry) { // port note (af9777b49): upstream's ImageConversation RAM-only rule,
        const e = kept;               // kept on the fork's Kept queue (TF_KV_SHARE pages)
        if (e.image_frame != 0 or e.images.len != 0 or !@import("cache_images.zig").diskSafe(e.tokens)) {
            if (!e.image_noted) pc.note("imprint: {d} tokens kept RAM-only (ImageConversation); image states are not written to disk", .{e.at});
            e.image_noted = true;
            return;
        }
        sync.queued(r, Kept.of(e), starts);
        return;
    }
    sync.queued(r, kept, starts);
}

/// The store's hold on a queued save given up: its pages released, its tokens freed (the store's own copies).
pub fn gave(_: *Rows, q: *const sync.Queued) void {
    if (q.kept.freed) |f| f.call(f.ctx, q.kept.owner);
}

